import{_ as e,o as t,c as r,a5 as i}from"./chunks/framework.CXroN2RO.js";const c=JSON.parse('{"title":"疑問から選ぶ読み順","description":"","frontmatter":{"title":"疑問から選ぶ読み順","study":{"source":"統合ガイド","status":"published","generated":true,"catalog":true,"section":"learning","format":"path","domain":"guide","collection":"questions","order":0,"summary":"整数・浮動小数点、メモリ確保、プログラムの起動、入力と描画、Webの疑問から関連する本文をたどる。"}},"headers":[],"relativePath":"guide/learning-paths.md","filePath":"guide/learning-paths.md"}'),l={name:"guide/learning-paths.md"};function o(n,a,s,h,d,m){return t(),r("div",null,[...a[0]||(a[0]=[i('<div id="読み進め方" class="study-legacy-anchor" aria-hidden="true"></div><h1 id="疑問から選ぶ読み順" tabindex="-1">疑問から選ぶ読み順 <a class="header-anchor" href="#疑問から選ぶ読み順" aria-label="Permalink to &quot;疑問から選ぶ読み順&quot;">​</a></h1><p>辞典を最初から順番に読む必要はありません。いまの疑問に関係する本文から選びます。</p><h2 id="整数はメモリにどう並ぶか" tabindex="-1">整数はメモリにどう並ぶか <a class="header-anchor" href="#整数はメモリにどう並ぶか" aria-label="Permalink to &quot;整数はメモリにどう並ぶか&quot;">​</a></h2><ol><li><a href="/study/data/integer-bits-and-bytes.html">整数をビット列・16進数・バイト列で読む</a>で、値、表記、符号の解釈、バイト順を分ける。</li><li><a href="/study/practice/data/integer-byte-observation.html">C++の整数・バイト列観察サンプル</a>で、型の幅と実メモリ、明示的なLE/BE形式を比較する。</li><li><a href="/study/runtime/cpp-internals/memory-layout.html">メモリレイアウトとアラインメント</a>で、オブジェクトを置く場所やパディングとの違いを調べる。</li></ol><h2 id="floatで小さな差が消えるのはなぜか" tabindex="-1">floatで小さな差が消えるのはなぜか <a class="header-anchor" href="#floatで小さな差が消えるのはなぜか" aria-label="Permalink to &quot;floatで小さな差が消えるのはなぜか&quot;">​</a></h2><ol><li><a href="/study/data/floating-point-spacing.html">floatが表せる値と丸め</a>で、binary32の有効精度、表現できる値の間隔、丸めを調べる。</li><li><a href="/study/practice/data/float-spacing-observation.html">C++のfloat観察サンプル</a>で、ビット表現、隣接値、2の冪の境界、epsilonの意味を確かめる。</li><li><a href="/study/math/rendering/transform.html">座標変換</a>と<a href="/study/math/rendering/camera.html">カメラ・深度</a>で、描画で数値の尺度を扱う場面へつなぐ。</li></ol><h2 id="「確保する」と内部で何が起きるか" tabindex="-1">「確保する」と内部で何が起きるか <a class="header-anchor" href="#「確保する」と内部で何が起きるか" aria-label="Permalink to &quot;「確保する」と内部で何が起きるか&quot;">​</a></h2><ol><li><a href="/study/runtime/memory/storage-duration-and-lifetime.html">記憶域期間・スコープ・寿命</a>を区別する。</li><li><a href="/study/runtime/memory/allocation-journey.html">malloc/newの内部</a>で、空き領域の再利用、必要時のOS要求、構築・破棄を追う。</li><li><a href="/study/os/virtual-memory.html">仮想メモリ</a>で、アドレス空間、ページ、予約・コミット・常駐、ページフォルトを区別する。</li><li><a href="/study/practice/memory/windows-memory-observation.html">Windows/C++の観察サンプル</a>で、予約・コミット・初回書込み・解放を実際に分けて確かめる。</li><li><a href="/study/runtime/memory/allocators-and-pools.html">用途別アロケータ</a>、<a href="/study/runtime/memory/memory-bugs.html">メモリバグ</a>、<a href="/study/runtime/memory/cache-locality-aos-soa.html">キャッシュ局所性</a>へ進む。</li></ol><h2 id="ソースコードがcpuで動くまで" tabindex="-1">ソースコードがCPUで動くまで <a class="header-anchor" href="#ソースコードがcpuで動くまで" aria-label="Permalink to &quot;ソースコードがCPUで動くまで&quot;">​</a></h2><ol><li><a href="/study/runtime/cpp-internals/build-pipeline-journey.html">ビルドの旅</a>でコンパイルとリンクをたどる。</li><li><a href="/study/runtime/cpp-internals/translation-units-and-headers.html">翻訳単位・ヘッダー</a>、<a href="/study/runtime/cpp-internals/symbols-and-linkage.html">シンボル・ABI</a>、<a href="/study/runtime/cpp-internals/object-files-and-libraries.html">実行ファイル・ライブラリ</a>を調べる。</li><li><a href="/study/os/process-startup.html">実行ファイルを起動してmainへ到達するまで</a>で、プロセス・スレッド、ローダー、CRTの役割を分ける。</li><li><a href="/study/practice/process/windows-process-observation.html">Windows/C++のプロセス観察</a>で、main前の記録、親子プロセス、ワーカースレッドのPID・TIDを確かめる。</li><li><a href="/study/runtime/cpp-internals/function-calls-and-cpu.html">関数呼び出し・レジスタ</a>へ進む。</li></ol><h2 id="入力からゲーム画面まで" tabindex="-1">入力からゲーム画面まで <a class="header-anchor" href="#入力からゲーム画面まで" aria-label="Permalink to &quot;入力からゲーム画面まで&quot;">​</a></h2><ol><li><a href="/study/game/patterns/game-loop-and-update.html">ゲームループ</a>で入力・更新・描画の時間を分ける。</li><li><a href="/study/game/ecs.html">ECS</a>でID、データ配置、Query、構成変更を調べる。</li><li><a href="/study/math/rendering/transform.html">座標変換</a>と<a href="/study/graphics/pipeline/overview.html">描画パイプライン</a>から画面へつなぐ。</li><li>作って試すなら<a href="/study/game/shooter-design.html">シューティングの設計</a>を読み、<a href="/study/game/shooter-cpp.html">C++版</a>または<a href="/study/game/shooter-unity.html">Unity版</a>へ進む。</li></ol><h2 id="urlを開いてからページが見えるまで" tabindex="-1">URLを開いてからページが見えるまで <a class="header-anchor" href="#urlを開いてからページが見えるまで" aria-label="Permalink to &quot;URLを開いてからページが見えるまで&quot;">​</a></h2><p><a href="/study/network/">ネットワーク</a>と<a href="/study/browser/">ブラウザ</a>の専用本文は準備中です。両ページには扱う範囲を記しています。学習計画と、既に読める詳しい説明を区別して増補します。</p><h2 id="作り方の変化を歴史から見る" tabindex="-1">作り方の変化を歴史から見る <a class="header-anchor" href="#作り方の変化を歴史から見る" aria-label="Permalink to &quot;作り方の変化を歴史から見る&quot;">​</a></h2><p><a href="/study/history/video-games.html">ビデオゲーム史</a>の作品・ハード・媒体・流通と、<a href="/study/guide/rendering/timeline.html">リアルタイム3D技術史</a>の技術の変化から、気になった仕組みへ進みます。</p>',17)])])}const f=e(l,[["render",o]]);export{c as __pageData,f as default};
